head.script:
// scwin.tData = {
//     "description" : "[FAIL] input dataType=float, maxlength 적용 시 '.' 문자가 maxlength 계산에 포함되어 '.' 가 잘리는 결함",
//     "validation" : [
//         "API 가이드: dataType=float 일 때 '+', '-', '.' 문자는 maxlength 계산에서 제외됩니다.",
//         "정상 기대 동작 (4월정기) : maxlength=5, dataType=float, setValue(123456.789) → blur 시 '12345.' 표시 ('.' 카운트 제외, 소수점 보존)",
//         "실제 결함 동작 (5월정기) : maxlength=5, dataType=float, setValue(123456.789) → blur 시 '12345' 표시 ('.' 잘림, 소수점 사라짐)"
//     ]
// };

scwin.onpageload = function () {
    // 사전 조건: focus → setValue 후  → blur 사이클로 maxlength 적용 트리거
    target_float.focus();
    target_float.setValue(123456.789);    
    setTimeout(function () {
        target_float.blur();
    }, 200);

    scwin.setReturnValue("[onpageload] 사전 조건 적용 완료");
    scwin.setReturnValue("  - target_float (dataType=float, maxlength=5) focus + setValue(123456.789) + blur");
    scwin.setReturnValue("");
    scwin.setReturnValue("[API 가이드 내용]");
    scwin.setReturnValue("datatype=float 일때 '+', '-', '.' 문자는 maxlength 계산에서 제외됩니다.");
    scwin.setReturnValue("");
    scwin.setReturnValue("[현재 DOM 값 확인 → '값 확인' 버튼 클릭]");
};

scwin.btn_setValue_onclick = function () {
    target_float.focus();
    target_float.setValue(123456.789);    
    setTimeout(function () {
        target_float.blur();
        scwin.setReturnValue("focus + setValue(123456.789) + blur 재실행 완료");
    }, 200);
};

scwin.btn_checkValue_onclick = function () {
    var floatVal = target_float.getFormattedValue();
    scwin.setReturnValue("target_float.getFormattedValue() : '" + floatVal + "'");
    scwin.setReturnValue("  4월정기 결과 : '12345.'");
    scwin.setReturnValue("  현재버전 결과 : '" + floatVal + "'");
};

scwin.btn_clear_onclick = function (e) {
    tbx_return.setValue("");
};

scwin.setReturnValue = function (strValue) {
    tbx_return.setValue(tbx_return.getValue() + strValue);
    tbx_return.setValue(tbx_return.getValue() + "\n");
};
